"use client"

import * as React from "react"
import { defineBasicExtension, type BasicExtension } from "prosekit/basic"
import { createEditor, union, type NodeJSON } from "prosekit/core"
import { definePlaceholder } from "prosekit/extensions/placeholder"
import { TextSelection } from "prosekit/pm/state"
import { ProseKit, useEditor, useEditorDerivedValue } from "prosekit/react"
import {
  IndentDecreaseIcon,
  IndentIncreaseIcon,
  MinusIcon,
  TableIcon,
} from "lucide-react"
import { cn } from "cn"

import {
  BlockHandle,
  DropIndicator,
  TableHandle,
} from "@/components/standard/prosekit/block-handles"
import {
  EDITOR_FRAME_CLASS,
  EditorContent,
  EditorShell,
  useIsClient,
  useProseKitChange,
  useProseKitEditable,
  type ProseKitValue,
} from "@/components/standard/prosekit/editor-frame"
import {
  BLOCK_OPTIONS,
  FormatToolbar,
  InlineFormatMenu,
  applyBlockType,
  type BasicEditor,
} from "@/components/standard/prosekit/format"
import {
  SuggestionMenu,
  suggestionTrigger,
  type SuggestionItem,
} from "@/components/standard/prosekit/suggestion-menu"
import {
  ToolbarButton,
  ToolbarGroup,
  ToolbarSeparator,
} from "@/components/standard/toolbar"

export type BlockEditorValue = ProseKitValue

const SLASH = suggestionTrigger("/")

/** Inserts a 3×3 table with a header row and puts the cursor in its first cell. */
function insertTable(editor: BasicEditor) {
  const start = editor.state.selection.from
  editor.commands.insertTable({ row: 3, col: 3, header: true })

  const { state } = editor
  let cell = -1
  state.doc.nodesBetween(
    Math.max(0, start - 1),
    state.doc.content.size,
    (node, pos) => {
      if (cell >= 0) {
        return false
      }
      const role = node.type.spec.tableRole
      if (role === "cell" || role === "header_cell") {
        cell = pos
        return false
      }
      return true
    }
  )
  if (cell >= 0) {
    const selection = TextSelection.near(state.doc.resolve(cell + 1))
    editor.view.dispatch(state.tr.setSelection(selection))
  }
}

function slashItems(editor: BasicEditor): SuggestionItem[] {
  const blocks: SuggestionItem[] = BLOCK_OPTIONS.map((option) => ({
    value: option.label,
    label: option.label,
    leading: option.icon,
    hint: option.hint,
    onSelect: () => applyBlockType(editor, option.value),
  }))
  return [
    ...blocks,
    {
      value: "Table",
      label: "Table",
      leading: <TableIcon />,
      onSelect: () => insertTable(editor),
    },
    {
      value: "Divider",
      label: "Divider",
      leading: <MinusIcon />,
      hint: "---",
      onSelect: () => editor.commands.insertHorizontalRule(),
    },
  ]
}

function SlashMenu() {
  const editor = useEditor<BasicExtension>()
  const items = React.useMemo(() => slashItems(editor), [editor])
  return <SuggestionMenu trigger={SLASH} items={items} />
}

function readInsertState(editor: BasicEditor) {
  return {
    canIndent: editor.commands.indentList.canExec(),
    canDedent: editor.commands.dedentList.canExec(),
  }
}

function InsertGroups({ editable }: { editable: boolean }) {
  const editor = useEditor<BasicExtension>()
  const state = useEditorDerivedValue(readInsertState)

  function run(command: () => void) {
    command()
    editor.focus()
  }

  return (
    <>
      <ToolbarSeparator />
      <ToolbarGroup aria-label="List indent">
        <ToolbarButton
          label="Outdent"
          hint="Outdent (Shift+Tab)"
          disabled={!editable || !state.canDedent}
          onClick={() => run(() => editor.commands.dedentList())}
        >
          <IndentDecreaseIcon />
        </ToolbarButton>
        <ToolbarButton
          label="Indent"
          hint="Indent (Tab)"
          disabled={!editable || !state.canIndent}
          onClick={() => run(() => editor.commands.indentList())}
        >
          <IndentIncreaseIcon />
        </ToolbarButton>
      </ToolbarGroup>
      <ToolbarSeparator />
      <ToolbarGroup aria-label="Insert">
        <ToolbarButton
          label="Insert table"
          hint="Insert table"
          disabled={!editable}
          onClick={() => run(() => insertTable(editor))}
        >
          <TableIcon />
        </ToolbarButton>
        <ToolbarButton
          label="Insert divider"
          hint="Insert divider"
          disabled={!editable}
          onClick={() => run(() => editor.commands.insertHorizontalRule())}
        >
          <MinusIcon />
        </ToolbarButton>
      </ToolbarGroup>
    </>
  )
}

type BlockEditorProps = {
  className?: string
  contentClassName?: string
  placeholder?: string
  /** Initial document as HTML or ProseKit JSON. Read once on mount. */
  defaultContent?: string | NodeJSON
  onChange?: (value: BlockEditorValue) => void
  editable?: boolean
  toolbar?: boolean
  "aria-label"?: string
}

// The left gutter holds the block handle.
const CONTENT_CLASS = "min-h-56 py-4 pr-4 pl-14"

function EditorSync({
  onChange,
  editable,
}: {
  onChange?: (value: BlockEditorValue) => void
  editable: boolean
}) {
  const editor = useEditor<BasicExtension>()
  useProseKitChange(editor, onChange)
  useProseKitEditable(editor, editable)
  return null
}

/**
 * Notion-style document editor on ProseKit: a Standard Toolbar, a "/" menu,
 * a format menu over selections, drag handles to reorder blocks, task and
 * toggle lists, tables and code blocks.
 */
function BlockEditor(props: BlockEditorProps) {
  const isClient = useIsClient()
  if (!isClient) {
    return (
      <EditorShell
        slot="block-editor"
        className={props.className}
        contentClassName={cn(CONTENT_CLASS, props.contentClassName)}
        toolbar={props.toolbar ?? true}
      />
    )
  }
  return <BlockEditorClient {...props} />
}

function BlockEditorClient({
  className,
  contentClassName,
  placeholder = "Type / for commands…",
  defaultContent,
  onChange,
  editable = true,
  toolbar = true,
  "aria-label": ariaLabel = "Document editor",
}: BlockEditorProps) {
  const [editor] = React.useState(() =>
    createEditor({
      extension: union(
        defineBasicExtension(),
        definePlaceholder({ placeholder, strategy: "block" })
      ),
      defaultContent,
    })
  )

  return (
    <ProseKit editor={editor}>
      <div
        data-slot="block-editor"
        data-editable={editable}
        className={cn(EDITOR_FRAME_CLASS, className)}
      >
        {toolbar ? (
          <FormatToolbar editable={editable}>
            <InsertGroups editable={editable} />
          </FormatToolbar>
        ) : null}
        <EditorContent
          editor={editor}
          aria-label={ariaLabel}
          className={cn(CONTENT_CLASS, contentClassName)}
        />
        {editable ? (
          <>
            <SlashMenu />
            <InlineFormatMenu />
            <BlockHandle />
            <TableHandle />
            <DropIndicator />
          </>
        ) : null}
        <EditorSync onChange={onChange} editable={editable} />
      </div>
    </ProseKit>
  )
}

export { BlockEditor }

"use client"

import type { Editor } from "prosekit/core"
import type { TableExtension } from "prosekit/extensions/table"
import { useEditorDerivedValue } from "prosekit/react"
import {
  BlockHandleAdd,
  BlockHandleDraggable,
  BlockHandlePopup,
  BlockHandlePositioner,
  BlockHandleRoot,
} from "prosekit/react/block-handle"
import { DropIndicator as DropIndicatorPrimitive } from "prosekit/react/drop-indicator"
import { MenuItem, MenuPopup, MenuPositioner } from "prosekit/react/menu"
import {
  TableHandleColumnMenuRoot,
  TableHandleColumnMenuTrigger,
  TableHandleColumnPopup,
  TableHandleColumnPositioner,
  TableHandleDragPreview,
  TableHandleDropIndicator,
  TableHandleRoot,
  TableHandleRowMenuRoot,
  TableHandleRowMenuTrigger,
  TableHandleRowPopup,
  TableHandleRowPositioner,
} from "prosekit/react/table-handle"
import { GripHorizontalIcon, GripVerticalIcon, PlusIcon } from "lucide-react"
import { cn } from "cn"

import {
  POPUP_CLASS,
  POPUP_ITEM_CLASS,
  POSITIONER_CLASS,
} from "@/components/standard/prosekit/editor-frame"

const HANDLE_POPUP_CLASS =
  "flex origin-(--transform-origin) transition transition-discrete duration-100 data-[state=closed]:scale-95 data-[state=closed]:opacity-0 starting:scale-95 starting:opacity-0 motion-reduce:transition-none"

const HANDLE_BUTTON_CLASS =
  "flex items-center justify-center rounded-sm text-muted-foreground/60 transition-colors hover:bg-muted hover:text-foreground [&_svg]:size-4"

/** The + and drag grip beside the hovered block. Needs a left gutter of about 3rem. */
export function BlockHandle() {
  return (
    <BlockHandleRoot>
      <BlockHandlePositioner placement="left" className={POSITIONER_CLASS}>
        <BlockHandlePopup className={HANDLE_POPUP_CLASS}>
          <BlockHandleAdd
            aria-label="Add block below"
            className={cn(HANDLE_BUTTON_CLASS, "size-6 cursor-pointer")}
          >
            <PlusIcon />
          </BlockHandleAdd>
          <BlockHandleDraggable
            aria-label="Drag to move block"
            className={cn(HANDLE_BUTTON_CLASS, "h-6 w-5 cursor-grab")}
          >
            <GripVerticalIcon />
          </BlockHandleDraggable>
        </BlockHandlePopup>
      </BlockHandlePositioner>
    </BlockHandleRoot>
  )
}

/** The line that shows where a dragged block will land. */
export function DropIndicator() {
  return <DropIndicatorPrimitive className="z-50 bg-primary transition-all" />
}

function readTableActions(editor: Editor<TableExtension>) {
  const { commands } = editor
  const action = (label: string, command: typeof commands.deleteTable) => ({
    label,
    canExec: command.canExec(),
    run: () => command(),
  })
  return {
    column: [
      action("Insert left", commands.addTableColumnBefore),
      action("Insert right", commands.addTableColumnAfter),
      action("Clear contents", commands.deleteCellSelection),
      action("Delete column", commands.deleteTableColumn),
    ],
    row: [
      action("Insert above", commands.addTableRowAbove),
      action("Insert below", commands.addTableRowBelow),
      action("Clear contents", commands.deleteCellSelection),
      action("Delete row", commands.deleteTableRow),
    ],
    deleteTable: action("Delete table", commands.deleteTable),
  }
}

type TableAction = ReturnType<typeof readTableActions>["deleteTable"]

function TableMenu({ actions }: { actions: TableAction[] }) {
  return (
    <MenuPositioner className={POSITIONER_CLASS}>
      <MenuPopup className={cn(POPUP_CLASS, "min-w-40 outline-none")}>
        {actions
          .filter((action) => action.canExec)
          .map((action) => (
            <MenuItem
              key={action.label}
              onSelect={action.run}
              data-danger={action.label === "Delete table" ? "" : undefined}
              className={POPUP_ITEM_CLASS}
            >
              {action.label}
            </MenuItem>
          ))}
      </MenuPopup>
    </MenuPositioner>
  )
}

const TABLE_TRIGGER_CLASS =
  "flex items-center justify-center overflow-clip rounded-sm border border-border bg-background p-0 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground [&_svg]:size-3.5"

/** Grips on the hovered row and column, each opening an insert/delete menu. */
export function TableHandle() {
  const actions = useEditorDerivedValue(readTableActions)

  return (
    <TableHandleRoot>
      <TableHandleDragPreview />
      <TableHandleDropIndicator />
      <TableHandleColumnPositioner className={POSITIONER_CLASS}>
        <TableHandleColumnPopup
          className={cn(HANDLE_POPUP_CLASS, "translate-y-1/2")}
        >
          <TableHandleColumnMenuRoot>
            <TableHandleColumnMenuTrigger
              aria-label="Column actions"
              className={cn(TABLE_TRIGGER_CLASS, "h-4 w-6")}
            >
              <GripHorizontalIcon />
            </TableHandleColumnMenuTrigger>
            <TableMenu actions={[...actions.column, actions.deleteTable]} />
          </TableHandleColumnMenuRoot>
        </TableHandleColumnPopup>
      </TableHandleColumnPositioner>
      <TableHandleRowPositioner placement="left" className={POSITIONER_CLASS}>
        <TableHandleRowPopup
          className={cn(HANDLE_POPUP_CLASS, "translate-x-1/2")}
        >
          <TableHandleRowMenuRoot>
            <TableHandleRowMenuTrigger
              aria-label="Row actions"
              className={cn(TABLE_TRIGGER_CLASS, "h-6 w-4")}
            >
              <GripVerticalIcon />
            </TableHandleRowMenuTrigger>
            <TableMenu actions={[...actions.row, actions.deleteTable]} />
          </TableHandleRowMenuRoot>
        </TableHandleRowPopup>
      </TableHandleRowPositioner>
    </TableHandleRoot>
  )
}

"use client"

import "prosekit/basic/style.css"

import * as React from "react"
import type { Node as ProseMirrorNode } from "prosekit/pm/model"
import type { Editor, NodeJSON } from "prosekit/core"
import { defineReadonly } from "prosekit/extensions/readonly"
import { useDocChange, useExtension } from "prosekit/react"
import { cn } from "cn"

export type ProseKitValue = {
  json: NodeJSON
  html: string
  text: string
}

/** The same bordered field as LexicalEditor and Textarea. */
export const EDITOR_FRAME_CLASS =
  "relative flex w-full flex-col rounded-lg border border-input bg-transparent text-sm focus-within:ring-3 focus-within:ring-ring/50 dark:bg-input/30"

// Positioners only place their popup; the popup draws the surface.
export const POSITIONER_CLASS = "z-50 block h-min w-min overflow-visible"

export const POPUP_CLASS =
  "box-border flex origin-(--transform-origin) flex-col rounded-lg bg-popover p-1 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 transition transition-discrete duration-100 data-[state=closed]:scale-95 data-[state=closed]:opacity-0 starting:scale-95 starting:opacity-0 motion-reduce:transition-none"

export const POPUP_ITEM_CLASS =
  "flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm whitespace-nowrap outline-hidden select-none data-highlighted:bg-muted data-[danger]:text-destructive [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground"

/** Mentions and hard breaks count as text; other atoms (images, rules) don't. */
function leafText(node: ProseMirrorNode) {
  if (node.type.name === "mention") {
    return String(node.attrs.value ?? "")
  }
  return node.type.name === "hardBreak" ? "\n" : ""
}

export function readProseKitValue(editor: Editor): ProseKitValue {
  const doc = editor.state.doc
  return {
    json: editor.getDocJSON(),
    html: editor.getDocHTML(),
    text: doc.textBetween(0, doc.content.size, "\n\n", leafText),
  }
}

/** Calls `onChange` with the document after every edit. */
export function useProseKitChange(
  editor: Editor,
  onChange: ((value: ProseKitValue) => void) | undefined
) {
  const onChangeRef = React.useRef(onChange)
  React.useEffect(() => {
    onChangeRef.current = onChange
  })

  const handleChange = React.useCallback(() => {
    onChangeRef.current?.(readProseKitValue(editor))
  }, [editor])

  useDocChange(handleChange, { editor })
}

/** Makes the document read-only while `editable` is false. */
export function useProseKitEditable(editor: Editor, editable: boolean) {
  const readonly = React.useMemo(
    () => (editable ? null : defineReadonly()),
    [editable]
  )
  useExtension(readonly, { editor })
}

const subscribeNever = () => () => {}

/** ProseKit parses HTML with the DOM, so editors are only created in the browser. */
export function useIsClient() {
  return React.useSyncExternalStore(
    subscribeNever,
    () => true,
    () => false
  )
}

/** What SSR renders in an editor's place: the same frame, toolbar row and height. */
export function EditorShell({
  slot,
  className,
  contentClassName,
  toolbar,
}: {
  slot: string
  className?: string
  contentClassName?: string
  toolbar?: boolean
}) {
  return (
    <div
      data-slot={slot}
      aria-busy="true"
      className={cn(EDITOR_FRAME_CLASS, className)}
    >
      {toolbar ? (
        <div className="h-10 rounded-t-lg border-b border-border bg-muted/30" />
      ) : null}
      <div className={cn("min-h-40 px-3 py-2", contentClassName)} />
    </div>
  )
}

/**
 * The element ProseKit mounts into. ProseMirror adds its own classes to it, so
 * keep `className` steady: a new value makes React overwrite them.
 */
export function EditorContent({
  editor,
  className,
  ...props
}: React.ComponentProps<"div"> & { editor: Editor }) {
  const mount = React.useCallback(
    (element: HTMLDivElement | null) => editor.mount(element),
    [editor]
  )

  return (
    <div
      ref={mount}
      data-slot="editor-content"
      className={cn(
        "typeset typeset-editor min-h-40 px-3 py-2 outline-none",
        className
      )}
      {...props}
    />
  )
}

"use client"

import * as React from "react"
import type { BasicExtension } from "prosekit/basic"
import type { Editor } from "prosekit/core"
import { useEditor, useEditorDerivedValue } from "prosekit/react"
import {
  InlinePopoverPopup,
  InlinePopoverPositioner,
  InlinePopoverRoot,
} from "prosekit/react/inline-popover"
import {
  BoldIcon,
  CodeIcon,
  CodeXmlIcon,
  Heading1Icon,
  Heading2Icon,
  Heading3Icon,
  ItalicIcon,
  LinkIcon,
  ListChecksIcon,
  ListCollapseIcon,
  ListIcon,
  ListOrderedIcon,
  PilcrowIcon,
  QuoteIcon,
  Redo2Icon,
  StrikethroughIcon,
  UnderlineIcon,
  Undo2Icon,
} from "lucide-react"
import { cn } from "cn"

import { Button } from "@/components/standard/button"
import {
  POPUP_CLASS,
  POSITIONER_CLASS,
} from "@/components/standard/prosekit/editor-frame"
import { Select, type SelectOption } from "@/components/standard/select"
import { TextField } from "@/components/standard/text-field"
import {
  Toolbar,
  ToolbarButton,
  ToolbarGroup,
  ToolbarSeparator,
  ToolbarToggle,
} from "@/components/standard/toolbar"

export type BasicEditor = Editor<BasicExtension>

export type BlockType =
  | "paragraph"
  | "h1"
  | "h2"
  | "h3"
  | "bullet"
  | "ordered"
  | "task"
  | "toggle"
  | "quote"
  | "code"

type ListKind = "bullet" | "ordered" | "task" | "toggle"

const LIST_KINDS: ListKind[] = ["bullet", "ordered", "task", "toggle"]
const HEADING_LEVELS = { h1: 1, h2: 2, h3: 3 } as const

function isListKind(type: BlockType): type is ListKind {
  return (LIST_KINDS as BlockType[]).includes(type)
}

export const BLOCK_OPTIONS: (SelectOption & {
  value: BlockType
  hint: string
})[] = [
  { value: "paragraph", label: "Text", hint: "", icon: <PilcrowIcon /> },
  { value: "h1", label: "Heading 1", hint: "#", icon: <Heading1Icon /> },
  { value: "h2", label: "Heading 2", hint: "##", icon: <Heading2Icon /> },
  { value: "h3", label: "Heading 3", hint: "###", icon: <Heading3Icon /> },
  { value: "bullet", label: "Bulleted list", hint: "-", icon: <ListIcon /> },
  {
    value: "ordered",
    label: "Numbered list",
    hint: "1.",
    icon: <ListOrderedIcon />,
  },
  { value: "task", label: "Task list", hint: "[]", icon: <ListChecksIcon /> },
  {
    value: "toggle",
    label: "Toggle list",
    hint: ">>",
    icon: <ListCollapseIcon />,
  },
  { value: "quote", label: "Quote", hint: ">", icon: <QuoteIcon /> },
  { value: "code", label: "Code block", hint: "```", icon: <CodeXmlIcon /> },
]

export function readBlockType(editor: BasicEditor): BlockType {
  const { nodes } = editor
  if (nodes.codeBlock.isActive()) {
    return "code"
  }
  for (const [type, level] of Object.entries(HEADING_LEVELS)) {
    if (nodes.heading.isActive({ level })) {
      return type as BlockType
    }
  }
  const kind = LIST_KINDS.find((item) => nodes.list.isActive({ kind: item }))
  if (kind) {
    return kind
  }
  return nodes.blockquote.isActive() ? "quote" : "paragraph"
}

/** Turns the blocks in the selection into `next`, unwrapping lists and quotes first. */
export function applyBlockType(editor: BasicEditor, next: BlockType) {
  const current = readBlockType(editor)
  const { commands } = editor
  if (current === next) {
    return
  }
  if (isListKind(current)) {
    commands.unwrapList()
  } else if (current === "quote") {
    commands.toggleBlockquote()
  }

  if (next === "code") {
    commands.setCodeBlock()
    return
  }
  if (next === "h1" || next === "h2" || next === "h3") {
    commands.setHeading({ level: HEADING_LEVELS[next] })
    return
  }
  commands.setParagraph()
  if (isListKind(next)) {
    commands.wrapInList({ kind: next })
  } else if (next === "quote") {
    commands.setBlockquote()
  }
}

export type MarkKey = "bold" | "italic" | "underline" | "strike" | "code"

const MARKS: {
  key: MarkKey
  label: string
  hint: string
  icon: React.ReactNode
  toggle: (editor: BasicEditor) => void
}[] = [
  {
    key: "bold",
    label: "Bold",
    hint: "Bold (Ctrl+B)",
    icon: <BoldIcon />,
    toggle: (editor) => editor.commands.toggleBold(),
  },
  {
    key: "italic",
    label: "Italic",
    hint: "Italic (Ctrl+I)",
    icon: <ItalicIcon />,
    toggle: (editor) => editor.commands.toggleItalic(),
  },
  {
    key: "underline",
    label: "Underline",
    hint: "Underline (Ctrl+U)",
    icon: <UnderlineIcon />,
    toggle: (editor) => editor.commands.toggleUnderline(),
  },
  {
    key: "strike",
    label: "Strikethrough",
    hint: "Strikethrough (Ctrl+Shift+S)",
    icon: <StrikethroughIcon />,
    toggle: (editor) => editor.commands.toggleStrike(),
  },
  {
    key: "code",
    label: "Inline code",
    hint: "Inline code (Ctrl+E)",
    icon: <CodeIcon />,
    toggle: (editor) => editor.commands.toggleCode(),
  },
]

function pickMarks(keys: MarkKey[] | undefined) {
  return keys ? MARKS.filter((mark) => keys.includes(mark.key)) : MARKS
}

function readLinkHref(editor: BasicEditor): string | undefined {
  const { $from, empty } = editor.state.selection
  const marks = empty ? $from.marks() : ($from.nodeAfter?.marks ?? [])
  const link = marks.find((mark) => mark.type.name === "link")
  return link ? String(link.attrs.href) : undefined
}

// Derived from the editor on every state change; keep it outside components.
function readFormatState(editor: BasicEditor) {
  const marks = {} as Record<MarkKey, boolean>
  for (const mark of MARKS) {
    marks[mark.key] = editor.marks[mark.key].isActive()
  }
  return {
    blockType: readBlockType(editor),
    marks,
    canUndo: editor.commands.undo.canExec(),
    canRedo: editor.commands.redo.canExec(),
    canLink: editor.commands.addLink.canExec({ href: "" }),
    href: readLinkHref(editor),
  }
}

function useFormatState() {
  return useEditorDerivedValue(readFormatState)
}

/**
 * Block type, history and text formats on the Standard Toolbar. `children`
 * adds groups after them (insert buttons, list indent).
 */
export function FormatToolbar({
  blockTypes,
  marks,
  editable = true,
  trailing,
  children,
}: {
  /** Which block types the Select offers. Defaults to all of them. */
  blockTypes?: BlockType[]
  /** Which text formats get a toggle. Defaults to all of them. */
  marks?: MarkKey[]
  editable?: boolean
  /** Pushed to the end of the bar, e.g. a view toggle. */
  trailing?: React.ReactNode
  children?: React.ReactNode
}) {
  const editor = useEditor<BasicExtension>()
  const state = useFormatState()
  const options = blockTypes
    ? BLOCK_OPTIONS.filter((option) => blockTypes.includes(option.value))
    : BLOCK_OPTIONS

  function run(command: () => void) {
    command()
    editor.focus()
  }

  return (
    <Toolbar aria-label="Formatting" className="rounded-t-lg">
      <Select
        appearance="toolbar"
        size="default"
        aria-label="Block type"
        placeholder="Block type"
        options={options}
        value={state.blockType}
        onValueChange={(next) =>
          run(() => applyBlockType(editor, next as BlockType))
        }
        disabled={!editable}
      />
      <ToolbarSeparator />
      <ToolbarGroup aria-label="History">
        <ToolbarButton
          label="Undo"
          hint="Undo (Ctrl+Z)"
          disabled={!editable || !state.canUndo}
          onClick={() => run(() => editor.commands.undo())}
        >
          <Undo2Icon />
        </ToolbarButton>
        <ToolbarButton
          label="Redo"
          hint="Redo (Ctrl+Shift+Z)"
          disabled={!editable || !state.canRedo}
          onClick={() => run(() => editor.commands.redo())}
        >
          <Redo2Icon />
        </ToolbarButton>
      </ToolbarGroup>
      <ToolbarSeparator />
      <ToolbarGroup aria-label="Text format">
        {pickMarks(marks).map((mark) => (
          <ToolbarToggle
            key={mark.key}
            label={mark.label}
            hint={mark.hint}
            disabled={!editable}
            pressed={state.marks[mark.key]}
            onPressedChange={() => run(() => mark.toggle(editor))}
          >
            {mark.icon}
          </ToolbarToggle>
        ))}
      </ToolbarGroup>
      {children}
      {trailing ? (
        <div className="ml-auto flex items-center">{trailing}</div>
      ) : null}
    </Toolbar>
  )
}

/**
 * Text formats and a link field that float over the selection. Clicks on the
 * bar don't take focus, so the selection stays put.
 */
export function InlineFormatMenu({ marks }: { marks?: MarkKey[] }) {
  const editor = useEditor<BasicExtension>()
  const state = useFormatState()
  const [linkOpen, setLinkOpen] = React.useState(false)
  const linkInput = React.useRef<HTMLInputElement>(null)

  // The popover shows a few frames after it renders, and a hidden input can't
  // take focus, so keep trying until it does.
  React.useEffect(() => {
    if (!linkOpen) {
      return
    }
    let timer = 0
    let tries = 0
    const focusInput = () => {
      const input = linkInput.current
      input?.focus()
      if (input && document.activeElement !== input && ++tries < 20) {
        timer = window.setTimeout(focusInput, 16)
      }
    }
    timer = window.setTimeout(focusInput, 0)
    return () => window.clearTimeout(timer)
  }, [linkOpen])

  function saveLink(href: string) {
    if (href) {
      editor.commands.addLink({ href })
    } else {
      editor.commands.removeLink()
    }
    setLinkOpen(false)
    editor.focus()
  }

  return (
    <>
      <InlinePopoverRoot
        onOpenChange={(event) => {
          if (!event.detail) {
            setLinkOpen(false)
          }
        }}
      >
        <InlinePopoverPositioner className={POSITIONER_CLASS}>
          <InlinePopoverPopup
            className={cn(POPUP_CLASS, "flex-row items-center gap-0.5")}
            onMouseDown={(event) => event.preventDefault()}
          >
            <ToolbarGroup aria-label="Text format">
              {pickMarks(marks).map((mark) => (
                <ToolbarToggle
                  key={mark.key}
                  label={mark.label}
                  pressed={state.marks[mark.key]}
                  onPressedChange={() => mark.toggle(editor)}
                >
                  {mark.icon}
                </ToolbarToggle>
              ))}
            </ToolbarGroup>
            {state.canLink ? (
              <>
                <ToolbarSeparator />
                <ToolbarToggle
                  label="Link"
                  pressed={state.href !== undefined || linkOpen}
                  onPressedChange={() => {
                    if (!linkOpen) {
                      editor.commands.expandLink()
                    }
                    setLinkOpen(!linkOpen)
                  }}
                >
                  <LinkIcon />
                </ToolbarToggle>
              </>
            ) : null}
          </InlinePopoverPopup>
        </InlinePopoverPositioner>
      </InlinePopoverRoot>

      <InlinePopoverRoot
        defaultOpen={false}
        open={linkOpen}
        onOpenChange={(event) => setLinkOpen(event.detail)}
      >
        <InlinePopoverPositioner
          placement="bottom"
          className={POSITIONER_CLASS}
        >
          <InlinePopoverPopup className={cn(POPUP_CLASS, "w-72 p-2")}>
            {linkOpen ? (
              <form
                className="flex items-center gap-1.5"
                onSubmit={(event) => {
                  event.preventDefault()
                  const input = event.currentTarget.elements.namedItem("href")
                  saveLink(
                    input instanceof HTMLInputElement ? input.value.trim() : ""
                  )
                }}
              >
                <TextField
                  name="href"
                  type="url"
                  aria-label="Link address"
                  placeholder="Paste a link…"
                  defaultValue={state.href}
                  ref={linkInput}
                  className="flex-1"
                />
                {state.href !== undefined ? (
                  <Button
                    type="button"
                    tone="ghost"
                    onMouseDown={(event) => event.preventDefault()}
                    onClick={() => saveLink("")}
                  >
                    Remove
                  </Button>
                ) : null}
              </form>
            ) : null}
          </InlinePopoverPopup>
        </InlinePopoverPositioner>
      </InlinePopoverRoot>
    </>
  )
}

"use client"

import * as React from "react"
import { canUseRegexLookbehind } from "prosekit/core"
import {
  AutocompleteEmpty,
  AutocompleteItem,
  AutocompletePopup,
  AutocompletePositioner,
  AutocompleteRoot,
} from "prosekit/react/autocomplete"
import { cn } from "cn"

import {
  POPUP_CLASS,
  POPUP_ITEM_CLASS,
  POSITIONER_CLASS,
} from "@/components/standard/prosekit/editor-frame"

export type SuggestionItem = {
  /** Matched against the typed query. Defaults to `label`. */
  value?: string
  label: React.ReactNode
  leading?: React.ReactNode
  /** Right-aligned hint, e.g. the Markdown shortcut for a block. */
  hint?: React.ReactNode
  onSelect: () => void
}

/**
 * Matches `trigger` plus the query after it at a word start: "/", "/head",
 * "@ana". A space straight after the trigger ("/ foo") closes the menu.
 */
export function suggestionTrigger(trigger: string) {
  const escaped = trigger.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")
  return new RegExp(
    (canUseRegexLookbehind() ? String.raw`(?<!\S)` : "") +
      escaped +
      String.raw`(\S.*)?$`,
    "u"
  )
}

export function SuggestionMenu({
  trigger,
  items,
  emptyLabel = "No results",
  className,
  onQueryChange,
  onOpenChange,
}: {
  trigger: RegExp
  items: SuggestionItem[]
  emptyLabel?: React.ReactNode
  className?: string
  onQueryChange?: (query: string) => void
  onOpenChange?: (open: boolean) => void
}) {
  return (
    <AutocompleteRoot
      regex={trigger}
      onQueryChange={(event) => onQueryChange?.(event.detail)}
      onOpenChange={(event) => onOpenChange?.(event.detail)}
    >
      <AutocompletePositioner className={POSITIONER_CLASS}>
        <AutocompletePopup
          className={cn(
            POPUP_CLASS,
            "max-h-80 min-w-56 overflow-y-auto overscroll-contain",
            className
          )}
        >
          <AutocompleteEmpty
            className={cn(POPUP_ITEM_CLASS, "text-muted-foreground")}
          >
            {emptyLabel}
          </AutocompleteEmpty>
          {items.map((item, index) => (
            <AutocompleteItem
              key={item.value ?? index}
              value={
                item.value ??
                (typeof item.label === "string" ? item.label : undefined)
              }
              onSelect={item.onSelect}
              className={cn(POPUP_ITEM_CLASS, "scroll-my-1")}
            >
              {item.leading}
              <span className="flex-1 truncate">{item.label}</span>
              {item.hint ? (
                <kbd className="font-mono text-xs text-muted-foreground">
                  {item.hint}
                </kbd>
              ) : null}
            </AutocompleteItem>
          ))}
        </AutocompletePopup>
      </AutocompletePositioner>
    </AutocompleteRoot>
  )
}
